// Spotify Web API is authoritative here: no HTML scraping and no baseline guessing.
// CrowdRelay owns durable deduplication via Idempotency-Key spotify:<release_id>,
// so this workflow keeps no seen-release business state.
function clean(value) { return String(value ?? '').trim(); }

function releaseFrom(item, index) {
  const id = clean(item?.id);
  const title = clean(item?.name);
  const date = clean(item?.release_date);
  if (!id || !title) return null;
  // A month- or year-precision release date cannot support an announcement.
  if (clean(item?.release_date_precision) !== 'day') return null;
  if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) return null;
  const totalTracks = Number(item?.total_tracks) || null;
  const albumType = clean(item?.album_type).toLowerCase();
  const releaseType = albumType === 'single' || totalTracks === 1
    ? 'single'
    : (totalTracks && totalTracks <= 6 ? 'ep' : 'album');
  const image = clean(item?.images?.[0]?.url);
  return {
    id,
    title,
    release_date: date,
    release_type: releaseType,
    listen_url: clean(item?.external_urls?.spotify) || `https://open.spotify.com/album/${id}`,
    cover_url: /^https:\/\//i.test(image) ? image : null,
    total_tracks: totalTracks,
    artist_name: 'Virya',
    // CrowdRelay accepts exactly "spotify" and rejects any other source with 400.
    source: 'spotify',
    site_url: 'https://virya.music/pl/',
    discovery_order: index
  };
}

const response = $input.first().json || {};
const items = Array.isArray(response.items) ? response.items : [];
if (!items.length) throw new Error('Spotify artist albums endpoint returned no items');

const manual = String($execution.mode || '').toLowerCase() === 'manual';
const now = new Date();
const parts = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Europe/Warsaw', year: 'numeric', month: '2-digit', day: '2-digit'
}).formatToParts(now).reduce((acc, part) => { acc[part.type] = part.value; return acc; }, {});
const today = `${parts.year}-${parts.month}-${parts.day}`;
const cutoff = new Date(`${today}T00:00:00Z`);
cutoff.setUTCDate(cutoff.getUTCDate() - 14);
const cutoffDate = cutoff.toISOString().slice(0, 10);

const normalized = [];
const seen = new Set();
for (let index = 0; index < items.length; index += 1) {
  const release = releaseFrom(items[index], index);
  if (!release || seen.has(release.id) || release.release_date > today) continue;
  seen.add(release.id);
  normalized.push(release);
}
normalized.sort((a, b) =>
  b.release_date.localeCompare(a.release_date) ||
  a.discovery_order - b.discovery_order ||
  a.id.localeCompare(b.id));
normalized.forEach(release => { delete release.discovery_order; });

if (manual) {
  const latest = normalized[0];
  return latest
    ? [{ json: { enqueue: false, status: 'manual_preview', release: latest, discovered_release_ids: items.length } }]
    : [{ json: { enqueue: false, status: 'release_metadata_unavailable', discovered_release_ids: items.length } }];
}

const recent = normalized.filter(release => release.release_date >= cutoffDate);
if (!recent.length) return [{ json: {
  enqueue: false,
  status: 'no_recent_release',
  checked_at: now.toISOString(),
  discovered_release_ids: items.length,
  parsed_release_count: normalized.length
} }];

return recent.map(release => ({ json: { enqueue: true, status: 'recent_release', release } }));
